return await (async run(input, context) {
    const articles = [
      {
        answer: "You can request a full refund within 30 days of purchase. Open Billing \u2192 Invoices, choose the invoice, and select Request refund. The refund goes back to the original payment method.",
        excerpt: "Refunds are available within 30 days from Billing \u2192 Invoices.",
        keywords: ["refund", "refunded", "money back", "cancel"],
        label: "Billing & refunds",
        suggestedReplies: [
          "Where can I find my invoice?",
          "I still need help with a refund"
        ]
      },
      {
        answer: "CSV exports are available on Growth and Scale plans. Go to Reports, choose a date range, then select Export CSV. Large exports finish in the background and appear in your download tray.",
        excerpt: "Reports \u2192 Export CSV supports Growth and Scale plans.",
        keywords: ["export", "csv", "download", "report"],
        label: "Reports & exports",
        suggestedReplies: [
          "Which plans include exports?",
          "My export is still processing"
        ]
      },
      {
        answer: "You can invite teammates from Settings \u2192 Members. Owners and admins can invite people; members can request access from their workspace admin.",
        excerpt: "Owners and admins manage invitations in Settings \u2192 Members.",
        keywords: ["invite", "member", "teammate", "access", "admin"],
        label: "Workspace access",
        suggestedReplies: [
          "What can each role do?",
          "I cannot access my workspace"
        ]
      }
    ], message = input.message.trim().slice(0, 800), normalized = message.toLowerCase(), article = articles.find((candidate) => candidate.keywords.some((keyword) => normalized.includes(keyword))) ?? {
      answer: "I can help with billing, reports, exports, and workspace access. Tell me what you are trying to do and I will point you to the right answer.",
      excerpt: "ResolveDesk currently covers billing, reports, and workspace access.",
      keywords: [],
      label: "ResolveDesk help center",
      suggestedReplies: ["How do refunds work?", "How do I export a report?"]
    };
    let answer = article.answer, mode = "grounded";
    const host = context, gatewayContext = context;
    if (host.sideModel)
      try {
        const generated = await host.sideModel({
          model_pref_key: "resolvedesk-support-model",
          prompt: [
            "Verified help-center excerpt:",
            article.excerpt,
            "Customer question:",
            message,
            "Reply in two concise sentences. Do not invent policy outside the excerpt."
          ].join(`
`),
          system: "You are a careful customer-support agent. Use only the verified help-center excerpt."
        });
        if (generated.trim()) {
          answer = generated.trim();
          mode = "ai";
        }
      } catch (error) {
        host.log?.("ResolveDesk side model unavailable; using grounded answer", error);
      }
    else if (gatewayContext.gateway)
      try {
        const generated = await gatewayContext.gateway.chat([
          {
            content: "You are a careful customer-support agent. Use only the verified help-center excerpt.",
            role: "system"
          },
          {
            content: [
              "Verified help-center excerpt:",
              article.excerpt,
              "Customer question:",
              message,
              "Reply in two concise sentences. Do not invent policy outside the excerpt."
            ].join(`
`),
            role: "user"
          }
        ]);
        if (generated.content.trim()) {
          answer = generated.content.trim();
          mode = "ai";
        }
      } catch {}
    const payload = {
      answer,
      handoff: !0,
      mode,
      sources: [{ excerpt: article.excerpt, label: article.label }],
      suggestedReplies: article.suggestedReplies
    };
    return {
      content: [{ type: "text", text: answer }],
      isError: !1,
      structuredContent: payload
    };
  })(input, host);

return await (async run(input) {
    return {
      content: [
        {
          text: `Handoff requested: ${input.message.trim().slice(0, 500)}`,
          type: "text"
        }
      ],
      isError: !1
    };
  })(input, host);
